(1) uCDN-A creates the trigger in tCDN-B:

POST /cit HTTP/1.1
User-Agent: example-user-agent/0.1
Host: tcdn.example
Accept: */*
Content-Type: application/cdni; ptype=ci-trigger.v2
Content-Length: 951

{
  "action": "preposition",
  "specs": [{
    "trigger-subject": "content",
    "cit-spec-type": "content-objectlist",
    "cit-spec-value": {
      "objects": [{
        "href": "https://www.example.com/hls/title/index.m3u8",
        "type": "hls"
      }]
    }
  }],
  "extensions": [
    {
      "cit-extension-type": "location-policy",
      "cit-extension-value": {
        "locations": [{
          "action": "allow",
          "footprints": [{
            "footprint-type": "countrycode",
            "footprint-value": [ "us" ]
          }]
        }]
      },
      "mandatory-to-enforce": true,
      "safe-to-redistribute": true
    },
    {
      "cit-extension-type": "time-policy",
      "cit-extension-value": {
        "unix-time-window": {
          "start": 1730174400,
          "end": 1730260800
        }
      },
      "mandatory-to-enforce": true,
      "safe-to-redistribute": true
    }
  ],
  "cdn-path": [ "AS64496:0" ]
}

(2) tCDN-B accepts the request and creates the trigger resource:

