    {
      "cit-extension-type": "time-policy",
      "cit-extension-value": {
        "unix-time-window": {
          "start": 1730174400,
          "end": 1730260800
        }
      },
      "mandatory-to-enforce": true,
      "safe-to-redistribute": true
    }
  ],
  "cdn-path": [ "AS64496:0" ]
}

