      "safe-to-redistribute": true
    }
  ],
  "cdn-path": [ "AS64496:0", "AS64500:0" ]
}

(4) dCDN-C does not support the "time-policy" extension and rejects the
    request. No trigger resource is created at dCDN-C:

HTTP/1.1 400 Bad Request
Date: Tue, 1 Sep 2026 08:48:32 GMT
Content-Type: application/cdni; ptype=ci-trigger-error.v2
Content-Length: 619
Server: example-server/0.1

{
  "error": "eextension",
  "description": "extension type time-policy is not supported",
  "specs": [{
    "trigger-subject": "content",
    "cit-spec-type": "content-objectlist",
    "cit-spec-value": {
      "objects": [{
        "href": "https://www.example.com/hls/title/index.m3u8",
        "type": "hls"
      }]
    }
  }],
  "extensions": [{
    "cit-extension-type": "time-policy",
    "cit-extension-value": {
      "unix-time-window": {
        "start": 1730174400,
        "end": 1730260800
      }
    },
    "mandatory-to-enforce": true,
    "safe-to-redistribute": true
  }],
  "cdn-id": "AS64501:0"
}

(5) uCDN-A queries the trigger resource in tCDN-B:

GET /cit/bcca1cde-ddf0-47db-b859-6a2c043baaa9 HTTP/1.1
User-Agent: example-user-agent/0.1
Host: tcdn.example
Accept: application/cdni; ptype=ci-trigger.v2

(6) tCDN-B reports the rejection from dCDN-C as an Error.v2 Description
    in its own trigger resource:

